         for (y=0; y < (ssize_t) image->rows; y+=rows)
         {
           register ssize_t
@@ -2478,8 +2479,10 @@ static void TIFFIgnoreTags(TIFF *tiff)
   ignore=(TIFFFieldInfo *) AcquireQuantumMemory(count,sizeof(*ignore));
   if (ignore == (TIFFFieldInfo *) NULL)
     return;
